import { Component, Input, OnInit, inject } from '@angular/core';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { ProyectoInversion } from '../../../../../../models/proyecto-inversion';
import { ProyectoInversionService } from '../../../../../../controllers/proyecto-inversion.service';
import { Tramite } from '../../../../../../models/tramite';
import { TramiteService } from '../../../../../../controllers/tramite.service';
import { DocumentoTramite } from '../../../../shared/documento-tramite/documento-tramite';

@Component({
  selector: 'app-datos-plan-negocios',
  standalone: true,
  imports: [ReactiveFormsModule, CommonModule, DocumentoTramite],
  templateUrl: './datos-plan-negocios.html',
  styleUrl: './datos-plan-negocios.css',
})
export class DatosPlanNegocios implements OnInit {
  form!: FormGroup;
  mostrarDescripcionFuera = false;
   
  status = {
    exito: false,
    error: false,
    mensaje: ''
  };

  private readonly fb = inject(FormBuilder);
  private readonly proyectoService = inject(ProyectoInversionService);
  private readonly tramiteService = inject(TramiteService);

  @Input() tramite: Tramite | null = null;

  async ngOnInit() {
    this.inicializarForm();
    if (this.tramite?.proyecto_inversion_id) await this.cargarDatosProyecto();
  }

  private inicializarForm() {
    this.form = this.fb.group({
      tipo_proyecto: ['', Validators.required],
      municipio: ['', Validators.required],
      domicilio: ['', [Validators.required, Validators.maxLength(255)]],
      numero_exterior: ['', [Validators.required, Validators.maxLength(20)]],
      numero_interior: ['', Validators.maxLength(20)],
      clave_catastral: ['', Validators.maxLength(50)],
      superficie: ['', Validators.min(0)],
      ubicacion_proyecto: ['', Validators.required],
      senalar_fuera_cabecera: ['', Validators.maxLength(500)],
      descripcion_proyecto: ['', Validators.required],
    });
  }

  private async cargarDatosProyecto() {
    const proyecto = await this.proyectoService.find(this.tramite!.proyecto_inversion_id!);
    if (!proyecto) return;

    const tipo_proyecto = proyecto.instalacion_nueva_empresa ? 'instalacion' 
                        : proyecto.desarrollo_tecnologia ? 'desarrollo' 
                        : proyecto.tratamiento_agua_residual ? 'tratamiento' : '';

    const ubicacion = proyecto.dentro_cabecera_municipal ? 'dentro' : 'fuera';
    this.mostrarDescripcionFuera = ubicacion === 'fuera';

    this.form.patchValue({
      ...proyecto,
      tipo_proyecto,
      ubicacion_proyecto: ubicacion,
      superficie: proyecto.superficie?.toString().replace(',', '.')
    });
  }

  async onGuardar() {
    this.status.exito = false;
    this.status.error = false;

    if (this.form.invalid) {
      this.status.error = true;
      this.status.mensaje = 'Por favor complete los campos marcados como obligatorios.';
      return;
    }

    const v = this.form.value;
    const datos: Partial<ProyectoInversion> = {
      ...v,
      localidad: 'Baja California',
      superficie: v.superficie ? parseFloat(v.superficie) : null,
      instalacion_nueva_empresa: v.tipo_proyecto === 'instalacion',
      desarrollo_tecnologia: v.tipo_proyecto === 'desarrollo',
      tratamiento_agua_residual: v.tipo_proyecto === 'tratamiento',
      dentro_cabecera_municipal: v.ubicacion_proyecto === 'dentro',
      fuera_cabecera_municipal: v.ubicacion_proyecto === 'fuera',
    };

    if (!this.tramite?.proyecto_inversion_id) {

      const nuevo = await this.proyectoService.new(datos,true);
      if (nuevo?.id) {
        const updateTramite = await this.tramiteService.update(this.tramite!.id, { 
          ...this.tramite, 
          proyecto_inversion_id: nuevo.id 
        });

        if (updateTramite.status) {
          this.tramite!.proyecto_inversion_id = nuevo.id;
          this.mostrarExito();
        } else {
          this.mostrarError('Error al vincular el proyecto con el trámite.');
        }
      } else {
        this.mostrarError('Error al crear el proyecto de inversión.');
      }
    } else {
      const updateResult = await this.proyectoService.update(this.tramite.proyecto_inversion_id, datos, true);
      if (updateResult.status) {
        this.mostrarExito();
      } else {
        this.mostrarError('Error al actualizar la información del proyecto.');
      }
    }
  }

  private mostrarExito() {
    this.status.exito = true;
    setTimeout(() => this.status.exito = false, 5000);
  }

  private mostrarError(msg: string) {
    this.status.mensaje = msg;
    this.status.error = true;
  }

  onUbicacionChange(ubicacion: string) {
    this.mostrarDescripcionFuera = ubicacion === 'fuera';
    if (ubicacion === 'dentro') this.form.get('senalar_fuera_cabecera')?.reset();
  }

  isFieldInvalid = (name: string) => {
    const f = this.form.get(name);
    return !!(f && f.invalid && (f.dirty || f.touched));
  }

  onSuperficieInput(event: Event) {
    const input = event.target as HTMLInputElement;
    let val = input.value.replace(/[^0-9.]/g, '');
    if ((val.match(/\./g) || []).length > 1) val = val.substring(0, val.lastIndexOf('.'));
    input.value = val;
    this.form.patchValue({ superficie: val });
  }
}