import { Component, EventEmitter, inject, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  ReactiveFormsModule,
  FormBuilder,
  FormGroup,
  Validators,
  AbstractControl,
} from '@angular/forms';
import { EmpresaService } from '../../../../controllers/empresa.service';
import { Empresa } from '../../../../models/empresa';
import { CodigoPostalService, MUNICIPIOS_BC } from '../../../../services/codigo-postal.service';

type TipoRegistro = 'MAQUILA' | 'SUBMAQUILA';

@Component({
  selector: 'app-empresa-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './empresa-form.html',
  styleUrl: './empresa-form.css',
})
export class EmpresaForm implements OnInit {
  @Input() empresaId?: number | null;
  @Output() empresaIdChange = new EventEmitter<number>();

  @Output() saved = new EventEmitter<Empresa>();
  @Output() canceled = new EventEmitter<void>();

  empresaForm: FormGroup = inject(FormBuilder).group({
    nombre_solicitante: ['', [Validators.required, Validators.minLength(3)]],
    actividad_giro: ['', [Validators.required]],
    rfc: [
      '',
      [
        Validators.required,
        Validators.pattern(
          /^[A-Za-z]{3,4}[0-9]{2}(0[1-9]|1[0-2])(0[1-9]|[12][0-9]|3[01])[A-Za-z0-9]{3}?$/
        ),
      ],
    ],
    escritura_constitutiva_volumen: [''],
    escritura_constitutiva_libro: [''],
    escritura_constitutiva_fecha: [''],
    nombre_notario: [''],
    numero_notario: [''],
    ciudad_notario: [''],
    estado_notario: [{ value: 'Baja California', disabled: true }, [Validators.required]],
    tipo_registro: [''],
    otro_tipo_registro: [''],
    codigo_postal: ['', [Validators.required, Validators.pattern(/^[0-9]{5}$/)]],
    calle: ['', [Validators.required]],
    numero_exterior: ['', [Validators.required]],
    numero_interior: [''],
    colonia: ['', [Validators.required]],
    municipio: ['', [Validators.required]],
    telefono: ['', [Validators.pattern(/^[0-9]{10}$/)]],
    pagina_web: [''],
    nombre_representante: ['', [Validators.required, Validators.minLength(3)]],
    escritura_publica_volumen: [''],
    escritura_publica_libro: [''],
    escritura_publica_fecha: [''],
    notario_publico: [''],
    numero_notario_representante: [''],
    ciudad_representante: [''],
    estado_representante: [{ value: 'Baja California', disabled: true }, [Validators.required]],
    persona_notificaciones: ['', [Validators.required, Validators.minLength(3)]],
    correo_electronico: ['', [Validators.required, Validators.email]],
    telefono_contacto: ['', [Validators.required, Validators.pattern(/^[0-9]{10}$/)]],
  });

  isEditMode = false;
  loading = false;
  submitted = false;
  empresa?: Empresa;

  tipoRegistroOptions: { value: TipoRegistro; label: string }[] = [
    { value: 'MAQUILA', label: 'Maquila' },
    { value: 'SUBMAQUILA', label: 'Submaquila' },
  ];

  municipiosOptions = MUNICIPIOS_BC;

  private fb = inject(FormBuilder);
  private empresaService = inject(EmpresaService);
  private codigoPostalService = inject(CodigoPostalService);

  async ngOnInit(): Promise<void> {
    const empresaId = this.empresaId

    this.isEditMode = !!empresaId

    await this.codigoPostalService.cargarCodigosPostales();

    this.empresaForm.get('codigo_postal')?.valueChanges.subscribe(() => {
      this.validarCodigoPostalConMunicipio();
    });

    this.empresaForm.get('municipio')?.valueChanges.subscribe(() => {
      this.validarCodigoPostalConMunicipio();
    });

    if (this.isEditMode && empresaId) {
      await this.loadEmpresaData(empresaId);
    }
  }

  private async loadEmpresaData(empresaId: number): Promise<void> {
    if (!empresaId) return;

    this.loading = true;
    this.empresa = await this.empresaService.find(empresaId);

    if (this.empresa) {
      this.empresaForm.patchValue(this.empresa);
    }
    this.loading = false;
  }

  get f(): Record<string, AbstractControl> {
    return this.empresaForm.controls;
  }

  validarCodigoPostalConMunicipio(): void {
    const codigoPostal = this.empresaForm.get('codigo_postal')?.value;
    const municipio = this.empresaForm.get('municipio')?.value;
    const codigoPostalControl = this.empresaForm.get('codigo_postal');

    if (codigoPostal && municipio && codigoPostalControl) {
      const valido = this.codigoPostalService.validarCodigoPostalParaMunicipio(codigoPostal, municipio);

      if (valido) {
        codigoPostalControl.setErrors(null);
      } else {
        codigoPostalControl.setErrors({ municipioInvalido: true });
      }
    }
  }

  async onSubmit(): Promise<void> {
    if (this.empresaForm.invalid) {
      this.empresaForm.markAllAsTouched();
      return;
    }

    const formData = this.empresaForm.value;

    if (this.isEditMode && this.empresa) {
      await this.empresaService.update(this.empresa.id, formData);
      this.empresa ={
        ...this.empresa,
        ...formData
      }
    } else {
      this.empresa =await this.empresaService.new(formData);
    }
    
    this.saved.emit(this.empresa);
    this.submitted = true;
  }

  onCancel(): void {
    this.canceled.emit();
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar Empresa' : 'Nueva Empresa';
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar Empresa' : 'Guardar Empresa';
  }
}
