import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { EmpresaForm } from "../../../shared/empresa-form/empresa-form";
import { Empresa } from '../../../../../models/empresa';
import { Tramite } from '../../../../../models/tramite';
import { TramiteService } from '../../../../../controllers/tramite.service';
import { EmpresaVinculadaForm } from "../../../shared/empresa-vinculada-form/empresa-vinculada-form";

@Component({
  selector: 'app-paso-2-cedula-sei',
  imports: [CommonModule, EmpresaForm, EmpresaVinculadaForm],
  templateUrl: './paso-2-cedula-sei.html',
  styleUrl: './paso-2-cedula-sei.css'
})
export class Paso2CedulaSei implements OnInit {
  showAgregarEmpresaVinculada = false;
  empresaBeneficiadaId?: number;

  tramite?: Tramite;

  private tramiteService = inject(TramiteService);

  async ngOnInit() {
    this.tramite = await this.tramiteService.getCurrentTramite(['empresa', 'empresa_vinculada']);
    
    if (this.tramite?.empresa_vinculada_id) {
      this.showAgregarEmpresaVinculada = true;
      this.empresaBeneficiadaId = this.tramite.empresa_beneficiada_id || this.tramite.empresa_id;
    } else {
      this.empresaBeneficiadaId = this.tramite?.empresa_id;
    }
  }

  empresaGuardada(empresa: Empresa) {
    if (!this.tramite) return;
    console.log(empresa,this.tramite)
    this.tramiteService.fastUpdate(this.tramite, { empresa_id: empresa.id });
  }

  empresaVinculadaGuardada(empresa: Empresa) {
    if (!this.tramite) return;
    this.tramiteService.fastUpdate(this.tramite, { empresa_vinculada_id: empresa.id });
  }

  toggleSeccionVinculada() {
    this.showAgregarEmpresaVinculada = !this.showAgregarEmpresaVinculada;
  }

  onEmpresaBeneficiadaChange(event: Event) {
    const select = event.target as HTMLSelectElement;
    this.empresaBeneficiadaId = Number(select.value);
  }
}
