import { Injectable } from "@angular/core";
import { SuperService } from "./super.service";
import { TramiteDocumento } from "../models/tramite-documento";
import { firstValueFrom } from "rxjs";

@Injectable({
    providedIn: 'root'
})
export class TramiteDocumentoService extends SuperService<TramiteDocumento> {
    protected model = 'tramite-documentos';
    protected columns: (keyof TramiteDocumento)[] = [
        'tramite_id',
        'url_documento',
        'nombre',
        'seccion',
        'deleted_at',
        'created_at',
        'updated_at'
    ];

    async obtenerDocumentoParaVisualizar(evidenciaId: number, loader = true): Promise<string | null> {
        const endpoint = `api/${this.model}/${evidenciaId}/view`;
        const response = await firstValueFrom(this.api.downloadFile(endpoint, loader));

        // Crear URL para visualización
        return window.URL.createObjectURL(response);
    }

    async verDocumento(documentoId: number, loader = true): Promise<boolean> {
        const visualUrl = await this.obtenerDocumentoParaVisualizar(documentoId, loader)
        if (visualUrl) {
            window.open(visualUrl, '_blank');
            return true;
        }
        return false;
    }
}
