import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';

export interface CodigoPostal {
  d_codigo: string;
  d_asenta: string;
  d_tipo_asenta: string;
  D_mnpio: string;
  d_estado: string;
  d_ciudad: string;
  d_CP: string;
  c_estado: string;
  c_oficina: string;
  c_CP: string;
  c_tipo_asenta: string;
  c_mnpio: string;
  id_asenta_cpcons: string;
  d_zona: string;
  c_cve_ciudad: string;
}

export const MUNICIPIOS_BC = [
  'Mexicali',
  'Tijuana',
  'Ensenada',
  'Rosarito',
  'San Felipe',
  'San Quintin',
  'Tecate',
] as const;

type MunicipioBC = (typeof MUNICIPIOS_BC)[number];

@Injectable({
  providedIn: 'root',
})
export class CodigoPostalService {
  private http = inject(HttpClient);
  private codigosPostales = new Map<string, MunicipioBC>();
  private loaded = false;

  async cargarCodigosPostales(): Promise<void> {
    if (this.loaded) return;

    try {
      const response = await fetch('/assets/core/data/codigos-postales-baja-california.csv');
      const text = await response.text();
      const lines = text.split('\n').slice(1);

      for (const line of lines) {
        if (!line.trim()) continue;

        const parts = line.split(',');
        if (parts.length >= 15) {
          const codigo = parts[0].replace(/"/g, '').trim();
          const municipio = parts[3].replace(/"/g, '').trim();

          if (MUNICIPIOS_BC.includes(municipio as MunicipioBC)) {
            this.codigosPostales.set(codigo, municipio as MunicipioBC);
          }
        }
      }

      this.loaded = true;
    } catch (error) {
      console.error('Error cargando códigos postales:', error);
    }
  }

  getMunicipioPorCodigoPostal(codigo: string): MunicipioBC | null {
    return this.codigosPostales.get(codigo) || null;
  }

  validarCodigoPostalParaMunicipio(codigo: string, municipio: string): boolean {
    const municipioDelCodigo = this.getMunicipioPorCodigoPostal(codigo);
    return municipioDelCodigo === municipio;
  }

  codigoPostalEsValido(codigo: string): boolean {
    return this.codigosPostales.has(codigo);
  }
}
