import { Component, Input, computed, OnChanges, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { StepConfig, StepWizardState } from './step.interface';
import { Tramite, TramiteTipo } from '../../../models/tramite';
import { Paso1EscritoLibre } from './steps/paso-1-escrito-libre/paso-1-escrito-libre';
import { Paso2CedulaSei } from './steps/paso-2-cedula-sei/paso-2-cedula-sei';
import { Paso3PlanNegocios } from './steps/paso-3-plan-negocios/paso-3-plan-negocios';
import { Paso4ActaConstitutiva } from './steps/paso-4-acta-constitutiva/paso-4-acta-constitutiva';
import { Paso5IdRepresentante } from './steps/paso-5-id-representante/paso-5-id-representante';
import { Paso6Cif } from './steps/paso-6-cif/paso-6-cif';
import { Paso7ComprobanteImpuestos } from './steps/paso-7-comprobante-impuestos/paso-7-comprobante-impuestos';
import { Paso8Anexo1Compromisos } from './steps/paso-8-anexo1-compromisos/paso-8-anexo1-compromisos';
import { Paso9Anexos } from './steps/paso-9-anexos/paso-9-anexos';
import { Paso10SolicitudEstimulo } from './steps/paso-10-solicitud-estimulo/paso-10-solicitud-estimulo';
import { Paso11ComprobantePago } from './steps/paso-11-comprobante-pago/paso-11-comprobante-pago';
import { Paso12Csf } from './steps/paso-12-csf/paso-12-csf';
import { TramiteService } from '../../../controllers/tramite.service';

const ALL_STEPS: StepConfig[] = [
  { id: 1, title: 'Escrito Libre', isConditional: true, component: Paso1EscritoLibre, isCompleted: false, isOptional: false },
  { id: 2, title: 'Cédula de la SEI', isConditional: true, component: Paso2CedulaSei, isCompleted: false, isOptional: false },
  { id: 3, title: 'Plan de Negocios o Proyecto de Inversión', isConditional: true, component: Paso3PlanNegocios, isCompleted: false, isOptional: false },
  { id: 4, title: 'Acta Constitutiva, Poder del Representante Legal', isConditional: false, component: Paso4ActaConstitutiva, isCompleted: false, isOptional: false },
  { id: 5, title: 'Identificación del Representante Legal', isConditional: false, component: Paso5IdRepresentante, isCompleted: false, isOptional: false },
  { id: 6, title: 'Cédula de Identificación Fiscal (CIF)', isConditional: false, component: Paso6Cif, isCompleted: false, isOptional: false },
  { id: 7, title: 'Comprobante del último pago de impuestos', isConditional: false, component: Paso7ComprobanteImpuestos, isCompleted: false, isOptional: false },
  { id: 8, title: 'Anexo 1 Formato de Compromisos', isConditional: false, component: Paso8Anexo1Compromisos, isCompleted: false, isOptional: false },
  { id: 9, title: 'Anexos (Esquema 3 al 14)', isConditional: false, component: Paso9Anexos, isCompleted: false, isOptional: false },
  { id: 10, title: 'Solicitud de Estímulo Fiscal', isConditional: false, component: Paso10SolicitudEstimulo, isCompleted: false, isOptional: false },
  { id: 11, title: 'Comprobante de Pago de Impuestos', isConditional: false, component: Paso11ComprobantePago, isCompleted: false, isOptional: false },
  { id: 12, title: 'CSF', isConditional: false, component: Paso12Csf, isCompleted: false, isOptional: false }
];

@Component({
  selector: 'app-status-tramite',
  imports: [
    CommonModule,
    Paso1EscritoLibre,
    Paso2CedulaSei,
    Paso3PlanNegocios,
    Paso4ActaConstitutiva,
    Paso5IdRepresentante,
    Paso6Cif,
    Paso7ComprobanteImpuestos,
    Paso8Anexo1Compromisos,
    Paso9Anexos,
    Paso10SolicitudEstimulo,
    Paso11ComprobantePago,
    Paso12Csf
  ],
  templateUrl: './status-tramite.html',
  styleUrl: './status-tramite.css'
})
export class StatusTramite implements OnChanges, OnInit {
  @Input() tramiteTipo: TramiteTipo = 'inversion_privada';
  @Input() tramite: Tramite | null = null;

  private tramiteService = inject(TramiteService);

  state: StepWizardState = {
    currentStep: 1,
    tramiteTipo: 'inversion_privada',
    steps: []
  };

  visibleSteps = computed(() => {
    return ALL_STEPS.filter(step => {
      if (step.isConditional) {
        return this.state.tramiteTipo === 'inversion_privada';
      }
      return true;
    });
  });

  totalSteps = computed(() => this.visibleSteps().length);

  get currentStepConfig(): StepConfig | undefined {
    return this.visibleSteps()[this.state.currentStep - 1];
  }

  get progressPercentage(): number {
    const visible = this.visibleSteps();
    const completed = visible.filter(s => s.isCompleted).length;
    return (completed / visible.length) * 100;
  }

  get completedSteps(): number {
    return this.visibleSteps().filter(s => s.isCompleted).length;
  }

  async ngOnInit(){
    this.tramite = await this.tramiteService.getCurrentTramite()??null;
    this.tramiteTipo = this.tramite?.tipo ?? 'inversion_privada';
    this.state.tramiteTipo = this.tramiteTipo;
    this.state.currentStep = 1;
  }

  ngOnChanges(): void {
    this.state.tramiteTipo = this.tramiteTipo;
    this.state.currentStep = 1;
  }

  goToStep(index: number): void {
    if (index >= 1 && index <= this.totalSteps()) {
      this.state.currentStep = index;
    }
  }

  nextStep(): void {
    if (this.state.currentStep < this.totalSteps()) {
      this.state.currentStep++;
    }
  }

  previousStep(): void {
    if (this.state.currentStep > 1) {
      this.state.currentStep--;
    }
  }

  markStepComplete(stepIndex: number): void {
    const step = this.visibleSteps()[stepIndex - 1];
    if (step) {
      step.isCompleted = true;
    }
  }

  isStepAccessible(stepIndex: number): boolean {
    if (stepIndex === 1) return true;
    const previousStep = this.visibleSteps()[stepIndex - 2];
    return previousStep?.isCompleted || false;
  }
}
