import { Component, computed, inject, OnInit, signal } from '@angular/core';
import { CommonModule, CurrencyPipe, PercentPipe } from '@angular/common';
import { Tramite } from '../../../../models/tramite';
import { TramiteAnexoEmpleo, TramiteNivel } from '../../../../models/tramite-anexo-empleo';
import { TramiteAnexoEmpleoIndirecto } from '../../../../models/tramite-anexo-empleo-indirecto';
import { TramiteService } from '../../../../controllers/tramite.service';
import { TramiteAnexoEmpleoService } from '../../../../controllers/tramite-anexo-empleo.service';
import { TramiteAnexoEmpleoIndirectoService } from '../../../../controllers/tramite-anexo-empleo-indirecto.service';
import { TramiteAnexoEmpleosDirectos } from '../tramite-anexo-empleos-directos/tramite-anexo-empleos-directos';
import { TramiteAnexoEmpleosIndirectos } from '../tramite-anexo-empleos-indirectos/tramite-anexo-empleos-indirectos';
import { VanillaDialogService } from '../../../../services/vanilla-dialog/vanilla-dialog.service';
import { filter, firstValueFrom } from 'rxjs';

interface Totales {
  empleosExistentes: number;
  empleosNuevos: number;
  totalEmpleos: number;
  porcentajeAumentoEmpleos: number;
  sueldoPromedioExistente: number;
  sueldoPromedioNuevo: number;
  porcentajeAumentoSueldo: number;
  sueldoTotalMensualExistente: number;
  sueldoTotalMensualNuevo: number;
  sueldoTotalMensualGeneral: number;
}

interface MonedaGrupo {
  moneda: string;
  registros: TramiteAnexoEmpleo[];
  totales: Totales;
}

interface NivelGrupo {
  nivel: string;
  nivelLabel: string;
  monedas: MonedaGrupo[];
  totales: Totales;
}

interface TotalGeneralMoneda {
  moneda: string;
  totales: Totales;
}

type NivelKey = TramiteNivel;

const NIVEL_LABELS: Record<NivelKey, string> = {
  DIRECCION: 'Dirección',
  ADMINISTRACION: 'Administración',
  SUPERVISION: 'Supervisión',
  PRODUCCION: 'Producción',
  OTRO: 'Otro'
};

const NIVEL_ORDER: NivelKey[] = ['DIRECCION', 'ADMINISTRACION', 'SUPERVISION', 'PRODUCCION', 'OTRO'];

@Component({
  selector: 'app-tramite-generacion-empleos',
  imports: [
    CommonModule,
    TramiteAnexoEmpleosDirectos,
    TramiteAnexoEmpleosIndirectos,
    CurrencyPipe,
    PercentPipe
  ],
  templateUrl: './tramite-generacion-empleos.html',
  styleUrl: './tramite-generacion-empleos.css',
})
export class TramiteGeneracionEmpleos implements OnInit {
  tramite = signal<Tramite | undefined>(undefined);
  anexosEmpleos = signal<TramiteAnexoEmpleo[]>([]);
  anexoEmpleoIndirecto = signal<TramiteAnexoEmpleoIndirecto | undefined>(undefined);
  showFormulario = signal(false);
  showFormularioIndirectos = signal(false);
  editingItem = signal<TramiteAnexoEmpleo | undefined>(undefined);
  loading = signal(false);

  anexosPorNivel = computed(() => this.agruparPorNivel());
  totalesGeneralesPorMoneda = computed(() => this.calcularTotalesGeneralesPorMoneda());
  totalesGenerales = computed(() => this.calcularTotalesGenerales());

  private tramiteService = inject(TramiteService);
  private tramiteAnexoEmpleoService = inject(TramiteAnexoEmpleoService);
  private tramiteAnexoEmpleoIndirectoService = inject(TramiteAnexoEmpleoIndirectoService);
  private dialog = inject(VanillaDialogService)

  async ngOnInit(): Promise<void> {
    this.loading.set(true);
    this.tramite.set(await this.tramiteService.getCurrentTramite(['anexosEmpleos', 'anexoEmpleoIndirecto']));
    const tramite = this.tramite();
    if (tramite?.anexos_empleos) {
      this.anexosEmpleos.set(tramite.anexos_empleos);
    }
    if (tramite?.anexo_empleo_indirecto) {
      this.anexoEmpleoIndirecto.set(tramite.anexo_empleo_indirecto);
    }
    this.loading.set(false);
  }

  private agruparPorNivel(): NivelGrupo[] {
    const anexos = this.anexosEmpleos();
    const grupos = new Map<string, NivelGrupo>();

    for (const nivel of NIVEL_ORDER) {
      grupos.set(nivel, {
        nivel,
        nivelLabel: NIVEL_LABELS[nivel],
        monedas: [],
        totales: this.crearTotalesVacios()
      });
    }

    const anexosPorNivel = new Map<string, TramiteAnexoEmpleo[]>();
    for (const anexo of anexos) {
      const nivel = anexo.nivel as NivelKey;
      if (!anexosPorNivel.has(nivel)) {
        anexosPorNivel.set(nivel, []);
      }
      anexosPorNivel.get(nivel)!.push(anexo);
    }

    for (const [nivel, registrosNivel] of anexosPorNivel) {
      const grupo = grupos.get(nivel);
      if (!grupo) continue;

      const monedasMap = new Map<string, TramiteAnexoEmpleo[]>();
      for (const registro of registrosNivel) {
        if (!monedasMap.has(registro.moneda)) {
          monedasMap.set(registro.moneda, []);
        }
        monedasMap.get(registro.moneda)!.push(registro);
      }

      for (const [moneda, registrosMoneda] of monedasMap) {
        grupo.monedas.push({
          moneda,
          registros: registrosMoneda,
          totales: this.calcularTotales(registrosMoneda)
        });
      }

      grupo.totales = this.calcularTotales(registrosNivel);
    }

    return Array.from(grupos.values()).filter(g => g.monedas.length > 0);
  }

  private calcularTotalesGeneralesPorMoneda(): TotalGeneralMoneda[] {
    const anexos = this.anexosEmpleos();
    const porMoneda = new Map<string, TramiteAnexoEmpleo[]>();

    for (const anexo of anexos) {
      if (!porMoneda.has(anexo.moneda)) {
        porMoneda.set(anexo.moneda, []);
      }
      porMoneda.get(anexo.moneda)!.push(anexo);
    }

    const resultados: TotalGeneralMoneda[] = [];
    for (const [moneda, registros] of porMoneda) {
      resultados.push({
        moneda,
        totales: this.calcularTotales(registros)
      });
    }

    return resultados;
  }

  private calcularTotalesGenerales(): Totales {
    return this.calcularTotales(this.anexosEmpleos());
  }

  private calcularTotales(registros: TramiteAnexoEmpleo[]): Totales {
    if (registros.length === 0) {
      return this.crearTotalesVacios();
    }

    const empleosExistentes = registros.reduce((sum, r) => sum + +(r.empleos_existentes || 0), 0);
    const empleosNuevos = registros.reduce((sum, r) => sum + +(r.empleos_nuevos || 0), 0);
    const totalEmpleos = empleosExistentes + empleosNuevos;

    const sueldosExistentes = registros
      .filter(r => r.sueldo_promedio_diario_existente && r.sueldo_promedio_diario_existente > 0);
    const sueldosNuevos = registros
      .filter(r => r.sueldo_promedio_diario_nuevo && r.sueldo_promedio_diario_nuevo > 0);

    const sueldoPromedioExistente = sueldosExistentes.length > 0
      ? sueldosExistentes.reduce((sum, r) => sum + +(r.sueldo_promedio_diario_existente || 0), 0) / sueldosExistentes.length
      : 0;

    const sueldoPromedioNuevo = sueldosNuevos.length > 0
      ? sueldosNuevos.reduce((sum, r) => sum + +(r.sueldo_promedio_diario_nuevo || 0), 0) / sueldosNuevos.length
      : 0;

    const porcentajeAumentoEmpleos = empleosExistentes > 0
      ? (empleosNuevos / empleosExistentes) * 100
      : 0;

    const porcentajeAumentoSueldo = sueldoPromedioExistente > 0
      ? ((sueldoPromedioNuevo - sueldoPromedioExistente) / sueldoPromedioExistente) * 100
      : 0;

    const sueldoTotalMensualExistente = empleosExistentes * sueldoPromedioExistente * 30;
    const sueldoTotalMensualNuevo = empleosNuevos * sueldoPromedioNuevo * 30;
    const sueldoTotalMensualGeneral = totalEmpleos * ((sueldoPromedioExistente + sueldoPromedioNuevo) / 2 || sueldoPromedioNuevo || sueldoPromedioExistente) * 30;

    return {
      empleosExistentes,
      empleosNuevos,
      totalEmpleos,
      porcentajeAumentoEmpleos,
      sueldoPromedioExistente,
      sueldoPromedioNuevo,
      porcentajeAumentoSueldo,
      sueldoTotalMensualExistente,
      sueldoTotalMensualNuevo,
      sueldoTotalMensualGeneral
    };
  }

  private crearTotalesVacios(): Totales {
    return {
      empleosExistentes: 0,
      empleosNuevos: 0,
      totalEmpleos: 0,
      porcentajeAumentoEmpleos: 0,
      sueldoPromedioExistente: 0,
      sueldoPromedioNuevo: 0,
      porcentajeAumentoSueldo: 0,
      sueldoTotalMensualExistente: 0,
      sueldoTotalMensualNuevo: 0,
      sueldoTotalMensualGeneral: 0
    };
  }

  abrirFormulario(item?: TramiteAnexoEmpleo): void {
    this.editingItem.set(item);
    this.showFormulario.set(true);
  }

  cerrarFormulario(): void {
    this.showFormulario.set(false);
    this.editingItem.set(undefined);
  }

  async onGuardar(item: TramiteAnexoEmpleo): Promise<void> {
    const currentAnexos = this.anexosEmpleos();
    const editing = this.editingItem();

    if (editing?.id) {
      const index = currentAnexos.findIndex(a => a.id === editing.id);
      if (index !== -1) {
        const nuevosAnexos = [...currentAnexos];
        nuevosAnexos[index] = item;
        this.anexosEmpleos.set(nuevosAnexos);
      }
    } else {
      this.anexosEmpleos.set([...currentAnexos, item]);
    }

    this.cerrarFormulario();
  }

  async onEliminar(id: number): Promise<void> {
    const confirmacion = await firstValueFrom(
      this.dialog.show({
        title: 'Eliminar registro de empleo',
        body: '¿Está seguro de eliminar este registro de empleo?',
        tipo: 'danger',
        respYes: 'Eliminar',
        respNo: 'Cancelar'
      }).pipe(filter(r => !!r))
    );
    if (!confirmacion.closedByAgree) return;

    const result = await this.tramiteAnexoEmpleoService.switch(id);
    if (result) {
      const currentAnexos = this.anexosEmpleos();
      this.anexosEmpleos.set(currentAnexos.filter(a => a.id !== id));
    }
  }

  abrirFormularioIndirectos(): void {
    this.showFormularioIndirectos.set(true);
  }

  cerrarFormularioIndirectos(): void {
    this.showFormularioIndirectos.set(false);
  }

  async onGuardarIndirectos(item: TramiteAnexoEmpleoIndirecto): Promise<void> {
    this.anexoEmpleoIndirecto.set(item);
    this.cerrarFormularioIndirectos();
  }

  getNivelLabel(nivel: string): string {
    return NIVEL_LABELS[nivel as NivelKey] || nivel;
  }

  getNivelColor(nivel: string): string {
    const colores: Record<NivelKey, string> = {
      DIRECCION: 'primary',
      ADMINISTRACION: 'success',
      SUPERVISION: 'info',
      PRODUCCION: 'warning',
      OTRO: 'secondary'
    };
    return colores[nivel as NivelKey] || 'secondary';
  }

  getTotalEmpleos(registro: TramiteAnexoEmpleo): number {
    return (+registro.empleos_existentes || 0) + (+registro.empleos_nuevos || 0);
  }

  getPorcentajeAumentoEmpleos(registro: TramiteAnexoEmpleo): number {
    if (!registro.empleos_existentes || registro.empleos_existentes === 0) return 0;
    return (+registro.empleos_nuevos / +registro.empleos_existentes) * 100;
  }

  getPorcentajeAumentoSueldo(registro: TramiteAnexoEmpleo): number {
    if (!registro.sueldo_promedio_diario_existente || registro.sueldo_promedio_diario_existente === 0) return 0;
    if (!registro.sueldo_promedio_diario_nuevo) return 0;
    return ((+registro.sueldo_promedio_diario_nuevo - +registro.sueldo_promedio_diario_existente) / +registro.sueldo_promedio_diario_existente) * 100;
  }

  getSueldoTotalMensual(registro: TramiteAnexoEmpleo): number {
    const totalEmpleos = this.getTotalEmpleos(registro);
    const sueldoPromedio = +(registro.sueldo_promedio_diario_nuevo || registro.sueldo_promedio_diario_existente || 0);
    return totalEmpleos * sueldoPromedio * 30;
  }
}
