import { Component, inject, Input, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Tramite } from '../../../../models/tramite';
import { TramiteService } from '../../../../controllers/tramite.service';
import { TramiteDocumento } from '../../../../models/tramite-documento';
import { TramiteDocumentoService } from '../../../../controllers/tramite-documento.service';
import { UtilsService } from '../../../../services/utils.service';

@Component({
  selector: 'app-documento-tramite',
  imports: [CommonModule],
  templateUrl: './documento-tramite.html',
  styleUrl: './documento-tramite.css',
})
export class DocumentoTramite implements OnInit {
  @Input() nombre = ''
  @Input() seccion =''

  tramite?: Tramite;
  tramiteDocumento ?: TramiteDocumento;

  file ?: File

  private tramiteService = inject(TramiteService);
  private tramiteDocumentoService = inject(TramiteDocumentoService);
  private utils = inject(UtilsService);

  async ngOnInit(){
    await this.setTramite()
    this.setTramiteDocumento()
  }

  private async setTramite(){
    this.tramite = await this.tramiteService.getCurrentTramite();
  }

  private async setTramiteDocumento(){
    if(!this.tramite){
      this.tramiteDocumento=undefined;
      return;
    }
    this.tramiteDocumento = await this.tramiteDocumentoService.first({
      conditionals: { seccion: this.seccion, tramite_id: this.tramite.id, deleted_at: null},
      loader: false,
    })
  }

  async guardarDocumento(data: Partial<TramiteDocumento>){
    if(!this.tramite){
      return;
    }
    if(this.tramiteDocumento){
      await this.tramiteDocumentoService.delete(this.tramiteDocumento)
    }

    data.seccion = this.seccion
    data.nombre = this.nombre
    data.tramite_id = this.tramite.id

    this.tramiteDocumento = await this.tramiteDocumentoService.new({
      data: data,
      file: this.file
    })
  }

  onFileSelected(event: Event){
    const inputElement = event.target as HTMLInputElement;
    if(inputElement.files && inputElement.files.length > 0){
      this.file = inputElement.files[0];
    }
  }

  verDocumento(){
    if(this.tramiteDocumento?.url_documento){
      this.tramiteDocumentoService.verDocumento(this.tramiteDocumento.id)
    }
  }
}
